/* Real Chromium against production bundle; synthetic examples generated by real APIs. */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),output=process.argv[2],fixturePath=process.argv[3];
if(!output||fs.existsSync(output)||!fixturePath)throw Error('NEW output path and fixture required');
const fixture=JSON.parse(fs.readFileSync(fixturePath));const {chromium}=require(process.env.PLAYWRIGHT_MODULE_DIR+'/playwright');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const started=performance.now(),results=[],errors=[],external=[],calls=[];
 const browser=await chromium.launch({headless:true,executablePath:process.env.BROWSER_EXECUTABLE});const context=await browser.newContext({viewport:{width:1440,height:1050}});const page=await context.newPage();page.setDefaultTimeout(6500);page.on('pageerror',e=>errors.push(e.message));
 let control={};const first=fixture.datasets[0],pdf=fixture.datasets[1],mainCandidate=first.responses['/candidates'].candidates[0];
 const safeJob=(ds,state)=>({...ds.job,state,events:state==='completed'?ds.job.events:[],attempt:state==='queued'?0:1,...(state==='failed'?{error_code:'workflow_internal_failure',error_category:'RETRYABLE'}:{error_code:null,error_category:null})});
 await page.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());
  if(u.origin!=='http://127.0.0.1:4173'){external.push(u.origin);return route.abort();}
  const reply=(body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
  if(u.pathname.startsWith('/api/')){calls.push({path:u.pathname,method:req.method(),headers:req.headers()});
   if(u.pathname==='/api/auth/status'){await delay(control.authDelay||0);return reply({provider_available:!control.unavailable,remote_enabled:control.remoteFlag??false});}
   if(u.pathname==='/api/auth/me')return control.anonymous?reply({},401):reply({user_id:'synthetic-reviewer',institution_id:'A',institution_name:control.long?'합성기관_광역행정업무지원센터_공동운영부서'.repeat(5):'합성 연구지원기관',role:control.role||'manager',institution_admin:true,csrf_token:'synthetic-csrf'});
   if(u.pathname==='/api/documents'&&req.method()==='POST'){return reply({document:doc(),duplicate:false},201);}
   if(u.pathname==='/api/documents'){const docs=structuredClone(fixture.documents).map(d=>d.id===first.document.id?doc():d);if(control.versions)docs.push({...doc(),id:'extra-version',number:23,active:false});if(control.foreignList)docs[0].institution_id='B';if(control.deregister)docs[0].registered=false;if(control.inactive)docs[0].active=false;return reply(docs);}
   const match=u.pathname.match(/^\/api\/documents\/([^/]+)\/versions\/([^/]+)(.*)$/);if(!match)return reply({},404);
   const ds=fixture.datasets.find(x=>x.document.document_id===match[1]&&x.document.id===match[2]);if(!ds){const doc=fixture.documents.find(d=>d.document_id===match[1]&&d.id===match[2]);return reply(doc||{},doc?200:404);}
   const tail=match[3];if(!tail){if(control.active&&control.failVerification)return reply({},500);if(control.deregister)return reply({},404);return reply(ds===first?doc():ds.document);}
   if(tail==='/parsing')return reply({id:'parse-'+match[2],version_id:match[2],state:control.parseState||'completed',attempt:control.newAttempt?2:1});
   if(tail==='/parsing/retry')return reply({id:'parse-'+match[2],version_id:match[2],state:'queued',attempt:2});
   if(tail.startsWith('/chunk-jobs')){if(req.method()==='POST'){assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');control.chunks=(control.chunks||0)+1;}return reply({id:'chunk-'+match[2],version_id:control.mixedChunk?'wrong':match[2],state:control.chunkState||'completed',parse_job_id:'parse-'+match[2],parse_attempt:1,attempt:1,generation:1});}
   if(tail==='/activate'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');control.activations=(control.activations||0)+1;await delay(control.activateDelay||0);if(control.activateLost){control.active=true;return route.abort();}if(control.activateNetwork)return route.abort();if(control.activateError)return reply({},control.activateError);control.active=true;return reply(doc());}
   if(tail==='/original'){await delay(control.pdfDelay||0);return route.fulfill({status:200,contentType:'application/pdf',body:Buffer.from(ds.original_pdf_base64,'base64')});}
   if(tail.includes('/chunks/')){if(control.resolveDelay)await delay(control.resolveDelay);if(control.resolveMissing)return reply({},404);if(control.resolveNetwork)return route.abort();assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');const ref=req.postDataJSON();let data=structuredClone(ds.resolved[ref.chunk_id]);if(control.badResolve)data.evidence.organization_id='B';return reply(data);}
   if(!tail.startsWith('/workflow'))return reply({},404);
   if(control.forbiddenAll)return reply({},403);
   const suffix=tail.slice('/workflow'.length);if(suffix==='/jobs'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');assert.deepEqual(req.postDataJSON(),{});control.posts=(control.posts||0)+1;await delay(control.submitDelay||0);return reply(safeJob(ds,control.enqueueFailed?'failed':'queued'),202);}
   if(suffix.endsWith('/retry')){control.retries=(control.retries||0)+1;return reply(safeJob(ds,'queued'),202);}
   if(suffix.endsWith('/cancel')){control.cancels=(control.cancels||0)+1;return reply(safeJob(ds,'cancelled'));}
   if(suffix.startsWith('/jobs/')){control.polls=(control.polls||0)+1;return reply(safeJob(ds,control.neverComplete?'processing':control.polls<2?'processing':'completed'));}
   if(suffix==='/candidates'&&control.workflowError){if(control.workflowError==='network')return route.abort();return reply({},control.workflowError);}
   if(control.evidenceMissing&&suffix.endsWith('/evidence'))return reply({},404);
   if(control.evidenceDelay&&suffix.endsWith('/evidence'))await delay(control.evidenceDelay);
   if(control.late&&ds===first&&suffix==='/candidates')await delay(1200);
   let data=structuredClone(ds.responses[suffix+u.search]||ds.responses[suffix]);if(!data)return reply({},404);
   if(control.critical&&Array.isArray(data.issues))data.issues.push({code:'SOURCE_CONFLICT',target_id:'workflow',severity:'ERROR',reason:'합성 중요 오류: 상충 근거를 확인해야 합니다.',auto_block:true,evidence_refs:[]});
   if(control.bigGraph&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence')){const c=data.candidates[0];c.steps=[...c.steps,...Array.from({length:96},(_,i)=>({...structuredClone(c.steps[i%4]),id:'stress_'+i}))];}
   if(control.empty&&suffix==='/candidates')data.candidates=[];
   if(control.unsafe)data.semantic_verification='VERIFIED';
   if(control.mixedGeneration&&suffix.startsWith('/form-links'))data.generation_id='another-generation';
   if(control.multipleEvidence&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].steps[0].actions.push(structuredClone(data.candidates[0].steps[1].label));
   if(control.foreignEvidence&&suffix.endsWith('/evidence'))data.evidence_refs[0].organization_id='B';
   if(control.unrenderable&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].edges[0].target='unknown-step';
   try{return await reply(data);}catch{return;}
  }
  const dist=path.resolve(root,process.env.V02C_DIST||'apps/web/dist'),file=path.resolve(dist,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(u.pathname==='/favicon.ico')return route.fulfill({status:204,body:''});if(!file.startsWith(dist+path.sep)||!fs.existsSync(file))return route.abort();return route.fulfill({body:fs.readFileSync(file),contentType:file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html'});
 });
 function doc(){return {...structuredClone(first.document),active:!!control.active,registered:!control.retired,state:control.documentState||'completed',original_name:control.long?'합성_행정매뉴얼_여러부서공동업무절차_'.repeat(12)+'.hwpx':first.document.original_name};}
 const baseline=process.env.V02C_BASELINE==='1',measures=[];let sequence=0;
 const captures=path.resolve(root,process.env.V02C_CAPTURE_DIR||'outputs/v02c/browser');
 async function check(name,fn){try{await fn();results.push({name,status:'PASS'});console.log('PASS '+name);}catch(e){results.push({name,status:'FAIL',error:e.message});console.log('FAIL '+name+': '+e.message);}}
 async function capture(name){fs.mkdirSync(captures,{recursive:true});const file=path.join(captures,name);if(fs.existsSync(file))throw Error('new capture path required');await page.screenshot({path:file,fullPage:true});}
 async function documents(width,options={}){control={long:true,versions:true,...options};await page.setViewportSize({width,height:900});await page.goto('http://127.0.0.1:4173/?case='+(++sequence)+'#/documents');await page.locator('tbody tr').first().waitFor();}
 async function workflow(width,options={}){control={active:true,...options};await page.setViewportSize({width,height:900});await page.goto('http://127.0.0.1:4173/?case='+(++sequence)+'#/workflows');await page.locator('.wf-candidate-bar').waitFor();await page.locator('.wf-original-quote').waitFor({state:'attached'});}
 async function overflow(){assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}
 async function touch(locator){const bounds=await locator.evaluateAll(nodes=>nodes.filter(n=>n.getClientRects().length).map(n=>({label:n.textContent.trim(),width:n.getBoundingClientRect().width,height:n.getBoundingClientRect().height})));assert.ok(bounds.length);assert.ok(bounds.every(b=>b.width>=43.5&&b.height>=43.5),JSON.stringify(bounds));return bounds;}
 try{
 for(const width of [320,375,430])await check('documents all columns visible without horizontal scrolling '+width,async()=>{await documents(width);const m=await page.locator('.documents-table').evaluate(el=>({scroll:el.scrollWidth,client:el.clientWidth,buttons:[...el.querySelectorAll('tbody button')].map(b=>({left:b.getBoundingClientRect().left,right:b.getBoundingClientRect().right,width:b.getBoundingClientRect().width,height:b.getBoundingClientRect().height})),rows:el.querySelectorAll('tbody tr').length}));measures.push({scenario:'documents',width,...m});if(!baseline){assert.ok(m.scroll<=m.client+1);assert.ok(m.buttons.every(b=>b.left>=0&&b.right<=width&&b.width>=44&&b.height>=44));assert.equal(await page.getByRole('row').filter({hasText:'버전 23'}).count(),1);}await overflow();if(width===375)await capture('documents-mobile.png');});
 await check('long institution header keeps logout/help readable and touchable',async()=>{await documents(320);await overflow();const m=await page.locator('.header-tools').evaluate(el=>({height:el.getBoundingClientRect().height,logout:[...el.querySelectorAll('button')].map(b=>({width:b.getBoundingClientRect().width,height:b.getBoundingClientRect().height,whiteSpace:getComputedStyle(b).whiteSpace})),help:[...el.querySelectorAll('a')].map(a=>({width:a.getBoundingClientRect().width,height:a.getBoundingClientRect().height}))}));measures.push({scenario:'long_institution_header',...m});if(!baseline){assert.ok(m.logout.every(b=>b.width>=44&&b.height>=44&&b.whiteSpace==='nowrap'));assert.ok(m.help.every(b=>b.width>=44&&b.height>=44));}});
 await check('desktop table still provides version and detail',async()=>{await documents(1440);assert.equal(await page.locator('table').evaluate(e=>getComputedStyle(e).display),'table');await capture('documents-desktop.png');});
 if(!baseline){
 await check('manager can open details and mobile activation confirmation with no overflow',async()=>{await documents(320,{long:false,versions:false});await page.locator('tbody tr').first().getByRole('button').click();await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).click();await page.getByRole('button',{name:'이 버전 활성화',exact:true}).click();await touch(page.locator('dialog[open] button'));await overflow();await capture('activation-mobile.png');await page.keyboard.press('Escape');assert.equal(await page.evaluate(()=>document.activeElement.textContent),'이 버전 활성화');});
 await check('reader has readable documents and no activation mutation',async()=>{await documents(375,{active:true,role:'reader',long:false});await page.locator('tbody tr').first().getByRole('button').click();await page.locator('.document-flow').waitFor();assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);assert.equal(await page.locator('.document-flow').getByRole('link').count(),0);await capture('reader-mobile.png');});
 }
 for(const width of [320,375,430])await check('mobile workflow prefers readable list '+width,async()=>{await workflow(width);const list=await page.locator('.wf-step-list').isVisible();measures.push({scenario:'mobile_initial_workflow',width,list_visible:list,node_count:await page.locator('.wf-map-node').count()});if(!baseline){assert.ok(list);assert.equal(await page.getByRole('button',{name:'단계 목록',exact:true}).getAttribute('aria-pressed'),'true');await touch(page.locator('.wf-step-list button'));await overflow();assert.ok(await page.locator('.wf-step-list button').first().locator('span').isVisible());}if(width===375)await capture('workflow-mobile.png');});
 await check('desktop map node fonts and controls measured',async()=>{await workflow(1440);const m=await page.locator('.wf-map-node').first().evaluate(e=>({title_px:parseFloat(getComputedStyle(e.querySelector('strong')).fontSize),caption_px:parseFloat(getComputedStyle(e.querySelector('.wf-node-caption')).fontSize)}));const b=await page.getByRole('button',{name:'지도 확대',exact:true}).boundingBox();measures.push({scenario:'map_readability',...m,zoom_button:b});if(!baseline){assert.ok(m.title_px>=16&&m.caption_px>=13);await touch(page.locator('.react-flow__controls button'));}await capture('workflow-desktop.png');});
 if(!baseline){
 await check('keyboard list selection opens correct source and preserves source/content distinction',async()=>{await workflow(375);const b=page.locator('.wf-step-list button').nth(1);await b.focus();assert.equal(await b.evaluate(e=>getComputedStyle(e).outlineWidth),'3px');await page.keyboard.press('Enter');await page.locator('.wf-original-quote').waitFor();assert.equal(await page.evaluate(()=>document.activeElement.textContent),'원문 근거 확인');assert.match(await page.locator('.wf-original-quote').innerText(),new RegExp(mainCandidate.steps[1].label.evidence[0].quote.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')));await page.locator('.wf-evidence-pane .status-badge').filter({hasText:'출처 확인'}).waitFor();assert.match(await page.locator('.wf-evidence-pane').innerText(),/내용 검토 필요/);await capture('evidence-mobile.png');await page.getByRole('tab',{name:'지도·단계'}).click();assert.equal(await page.locator('.wf-step-list button').nth(1).getAttribute('aria-pressed'),'true');});
 await check('mobile map can zoom, restore readable selected node, retain relations',async()=>{await workflow(375);await page.getByRole('button',{name:'지도',exact:true}).click();const edges=await page.locator('.react-flow__edge').count();const before=await page.locator('.react-flow__viewport').getAttribute('style');await page.getByRole('button',{name:'지도 확대',exact:true}).focus();assert.equal(await page.getByRole('button',{name:'지도 확대',exact:true}).evaluate(e=>getComputedStyle(e).outlineWidth),'3px');await page.keyboard.press('Enter');await page.waitForTimeout(200);assert.notEqual(await page.locator('.react-flow__viewport').getAttribute('style'),before);await page.getByRole('button',{name:'지도 축소',exact:true}).click();await page.getByRole('button',{name:'전체 지도 보기',exact:true}).click();await page.getByRole('button',{name:'선택 단계 크게 보기',exact:true}).click();await page.waitForTimeout(100);const m=await page.locator('.wf-map-node').first().evaluate(e=>({rendered_title_height:e.querySelector('strong').getBoundingClientRect().height,css_title_px:parseFloat(getComputedStyle(e.querySelector('strong')).fontSize),scale:e.getBoundingClientRect().width/e.offsetWidth}));measures.push({scenario:'mobile_selected_map',...m});assert.ok(m.scale>=0.95);await touch(page.locator('.react-flow__controls button'));assert.equal(await page.locator('.react-flow__edge').count(),edges);await capture('map-mobile.png');});
 await check('branch/backtrack relations and severe issues remain available',async()=>{await workflow(375,{critical:true});const all=page.getByText(/전체 검토 항목/);if(!await all.evaluate(e=>e.parentElement.open))await all.click();await page.getByText('합성 중요 오류: 상충 근거를 확인해야 합니다.',{exact:true}).waitFor();assert.ok(await page.locator('.wf-issue-list li').count()>0);await page.locator('.wf-relationships summary').click();assert.match(await page.locator('.wf-relationships').innerText(),/보완|조건|분기|반복/);assert.equal(await page.getByRole('button',{name:/승인|공식 게시/}).count(),0);});
 await check('layout and text 200 percent reflow without horizontal page scrolling',async()=>{for(const screen of ['documents','workflow']){if(screen==='documents')await documents(320);else await workflow(320);await page.addStyleTag({content:'body { font-size: 200%; }'});await overflow();}});
 await check('switch list/map does not query metadata or candidates again',async()=>{await workflow(375);const n=calls.length;await page.getByRole('button',{name:'지도',exact:true}).click();await page.getByRole('button',{name:'단계 목록',exact:true}).click();await page.waitForTimeout(100);assert.equal(calls.length,n);});
 await check('technical flags stay closed and severe issue wording is not approval',async()=>{await workflow(375);assert.doesNotMatch(await page.locator('.wf-trust').innerText(),/NOT_VERIFIED|NOT_REQUESTED/);assert.match(await page.locator('.wf-trust details').textContent(),/NOT_VERIFIED.*NOT_REQUESTED/);assert.match(await page.locator('.wf-trust').innerText(),/내용 검토 필요/);});
 await check('source labels and map controls have measured AA text contrast',async()=>{await workflow(1440);const pairs=await page.locator('.wf-node-caption, .wf-node-caption > span, .wf-map-node strong, .react-flow__controls button').evaluateAll(els=>els.map(el=>{let node=el,bg='rgb(255, 255, 255)';while(node){const b=getComputedStyle(node).backgroundColor;if(b!=='rgba(0, 0, 0, 0)'&&b!=='transparent'){bg=b;break;}node=node.parentElement;}return {text:el.textContent.trim().slice(0,40),fg:getComputedStyle(el).color,bg};}));function lum(c){const a=c.match(/[\d.]+/g).slice(0,3).map(Number).map(v=>{v/=255;return v<=0.04045?v/12.92:((v+0.055)/1.055)**2.4;});return a[0]*.2126+a[1]*.7152+a[2]*.0722;}for(const p of pairs){const a=lum(p.fg),b=lum(p.bg);p.ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);assert.ok(p.ratio>=4.5,JSON.stringify(p));}measures.push({scenario:'computed_text_contrast',minimum_ratio:Math.min(...pairs.map(p=>p.ratio)),pairs});});
 await check('visible technical disclosures retain at least 44px target height',async()=>{await workflow(375);const bounds=await page.locator('.wf-map-pane summary').evaluateAll(els=>els.filter(e=>e.getClientRects().length).map(e=>({text:e.textContent,width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height})));assert.ok(bounds.length);assert.ok(bounds.every(b=>b.width>=44&&b.height>=44),JSON.stringify(bounds));measures.push({scenario:'disclosure_targets',minimum_height:Math.min(...bounds.map(b=>b.height))});});
 await check('no exceptions, external requests or sensitive browser storage',async()=>{assert.deepEqual(errors,[]);assert.deepEqual(external,[]);assert.equal(await page.evaluate(()=>localStorage.length+sessionStorage.length),0);});
 }
 } finally {await browser.close();}
 const report={scope:baseline?'v0.2-B baseline measurements only':'v0.2-C Chromium production bundle + synthetic mocked HTTP',results,counts:{PASS:results.filter(r=>r.status==='PASS').length,FAIL:results.filter(r=>r.status==='FAIL').length},measurements:measures,seconds:(performance.now()-started)/1000,external,errors,actual_external_provider_calls:0};fs.writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));if(report.counts.FAIL)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
